      const ratingclassfication = await admission.classificationRatingsScreen.getselectedClassfication()
      await admission.classificationRatingsScreen.clickAddButtonButton()
      await admission.classificationRatingsScreen.Save()
      await admission.module.switchToClassificationRating()
      await admission.classificationRatingsScreen.verifyAtClassificationByScore(0)
      await loaderPage.navigateToModule('Facility Management')
      await loaderPage.navigateToScreen('Classification Search')
